  const HEAD = /^((?:schedule|annex(?:ure)?|appendix|exhibit|part)\s+[A-Z0-9]+\b.{0,70}|(?:clause|section|article)\s+\d+(?:\.\d+)*\b.{0,60}|\d+(?:\.\d+){0,3}\.?\s+[A-Z][A-Za-z&/,' -]{2,70})$/;
