  ACT.newSession = () => { const d = P(); const last = d.sessions.slice().sort((a, b) => (b.no || 0) - (a.no || 0))[0]; sessionDrawer({ id: '', no: (last ? last.no : 0) + 1, title: '', date: '', start: last ? last.start : '11:00', end: '', minutes: d.settings.defaultMinutes, modules: [], topics: '', participants: '', prep: '', status: 'planned', notes: '', mode: d.settings.mode }); };
